<script setup>
import { ref, computed, onMounted } from 'vue'
import { onShow, onHide } from '@dcloudio/uni-app'
import AppNavBar from './AppNavBar.vue'
import AppIcon from './AppIcon.vue'
import MenuGroup from './MenuGroup.vue'
import SelfAccountDetails from './SelfAccountDetails.vue'
import { loadCloudProfile } from '../services/cloud-profile.js'
import { getSession } from '../services/session.js'
import { wechatAuth } from '../services/wechat-auth.js'
import { isCommerceEnabled } from '../services/config.js'
const profile=ref(null),busy=ref(false),error=ref(''),linkOpen=ref(false)
const name=computed(()=>profile.value?.members.find(m=>m.relation==='本人')?.name||getSession()?.accountName||'我')
let epoch=0
async function load(){if(busy.value)return;const mine=++epoch;profile.value=null;error.value='';busy.value=true;try{const account=await wechatAuth.restore();if(mine!==epoch)return;if(!account){uni.reLaunch({url:'/pages/index/index'});return}const result=await loadCloudProfile();if(mine===epoch)profile.value=result}catch(e){if(mine===epoch)error.value=e.message}finally{if(mine===epoch)busy.value=false}}
function discard(){epoch++;busy.value=false;profile.value=null;error.value='';linkOpen.value=false}
onMounted(load);onShow(load);onHide(discard)
function go(url){uni.navigateTo({url})}
function unavailable(name){uni.showModal({title:name,content:'这项功能的正式服务尚未接入，开通后可在这里使用。',showCancel:false})}
function logout(){uni.showModal({title:'退出账号？',content:'已保存的云端家庭资料不会删除。',success:r=>{if(r.confirm){discard();wechatAuth.logout();uni.reLaunch({url:'/pages/index/index'})}}})}
</script>
<template><view class="screen cloud-my"><AppNavBar><view class="nav-row"><button class="icon-button" @click="uni.navigateBack({fail:()=>uni.reLaunch({url:'/pages/chat/index'})})">‹</button><text class="nav-title">我的</text><text/></view></AppNavBar><view class="profile-heading"><view class="profile-avatar"><AppIcon name="user" :size="52"/></view><view><text>{{name}}</text><text>照顾自己，也照顾家人的每一餐</text></view></view><text v-if="busy" class="safe-note">正在读取云端资料…</text><view v-if="error" class="card error-state"><text class="inline-error">{{error}}</text><button class="secondary-button" @click="load">重新读取</button></view><button class="family-card card" @click="go('/pages/profile/index')"><view class="family-icon"><AppIcon name="family" :size="46"/></view><view><text>{{profile?.householdName||'我的家'}} · {{profile?.members.length??'—'}}位成员</text><text>查看与管理家庭健康档案</text></view><text>›</text></button><view v-if="profile" class="mode-row card"><text>使用方式</text><view><text>{{profile.usageMode}}</text><button @click="go('/pages/onboarding/index')">更改</button></view></view><MenuGroup title="饮食与反馈" :items="[{icon:'record',name:'饮食记录',desc:'查看云端已确认的记录与更正',url:'/pages/records/index'},{icon:'record',name:'实测指标',desc:'体重、血糖、血压与趋势回顾',url:'/pages/indicators/index'}]" @go="go"/><MenuGroup v-if="isCommerceEnabled" title="食材与订单" :items="[{icon:'calendar',name:'今日食材采购',desc:'来自当前保存的餐单',url:'/pages/purchase/index?source=daily'},{icon:'order',name:'我的订单',desc:'查看商城订单与配送',url:'/pages/orders/index'},{icon:'family',name:'收货地址',desc:'管理当前账号的配送地址',url:'/pages/address/index'}]" @go="go"/><view class="group"><text class="group-title">资料与账号</text><view class="menu-list card"><button @click="go('/pages/family-select/index')">切换或加入家庭 <text>›</text></button><button @click="go('/pages/health/plans')">餐单与正式采用 <text>›</text></button><button @click="linkOpen=!linkOpen">本人健康档案与咨询授权 <text>›</text></button><button @click="go('/pages/settings/privacy')">隐私与账号 <text>›</text></button><button @click="unavailable('AI专属计划')">AI专属计划 <text>›</text></button></view></view><SelfAccountDetails v-if="linkOpen&&profile"/><button class="secondary-button logout" @click="logout">退出登录</button><text class="safe-note note">资料按当前账号和家庭读取，以服务端保存结果为准。</text></view></template>
<style scoped>.cloud-my{padding-bottom:60rpx}.profile-heading{display:flex;align-items:center;gap:24rpx;margin:36rpx 0}.profile-avatar,.family-icon{display:flex;align-items:center;justify-content:center;background:#eaf2ed;color:#246b50;flex-shrink:0}.profile-avatar{height:104rpx;width:104rpx;border-radius:50%}.profile-heading>view+view{display:flex;flex-direction:column;gap:10rpx}.profile-heading text:first-child{font-size:42rpx;font-weight:600}.profile-heading text:last-child{font-size:25rpx;color:#63636b}.family-card{border-radius:28rpx;background:#fff;border:1rpx solid #ebebef;width:100%;display:flex;align-items:center;gap:20rpx;padding:32rpx;text-align:left}.family-icon{height:84rpx;width:84rpx;border-radius:24rpx}.family-card>view:nth-child(2){flex:1;display:flex;flex-direction:column;gap:12rpx}.family-card>view:nth-child(2)>text:first-child{font-size:32rpx;font-weight:600}.family-card>view:nth-child(2)>text+text{font-size:25rpx;color:#63636b}.family-card>text{font-size:40rpx;color:#999}.mode-row{display:flex;justify-content:space-between;padding:28rpx 32rpx;margin-top:18rpx;font-size:29rpx}.mode-row>view{display:flex;gap:20rpx;align-items:center;font-size:26rpx;color:#63636b}.mode-row button{color:#246b50;min-height:64rpx}.group{margin-top:36rpx}.group-title{display:block;margin:0 0 14rpx 28rpx;font-size:25rpx;color:#63636b}.menu-list{padding:0 28rpx}.menu-list button{display:flex;justify-content:space-between;width:100%;padding:28rpx 0;min-height:104rpx;text-align:left;border-bottom:1rpx solid #ededf0;font-size:29rpx}.menu-list button:last-child{border:0}.menu-list text{color:#999}.logout{width:100%;margin-top:36rpx}.note{font-size:23rpx;margin-top:30rpx}.error-state{padding:24rpx;margin:24rpx 0}</style>
